/** An error answer: HTTP status, the stable reason (API_KEY_INVALID, RATE_LIMIT_EXCEEDED…) and Retry-After seconds. */
class ApiError(val status: Int, val reason: String?, message: String, val retryAfter: Double?, val body: String) : IOException(message)

/** The N-Ways Maps Platform API. Calls block: run them off the main thread (a coroutine on Dispatchers.IO). */
class NWaysClient(
    private val apiKey: String,
    baseUrl: String = "https://nways.ng",
    private val headers: Map<String, String> = emptyMap(),
    private val timeoutMs: Int = 10_000,
) {
    private val base = baseUrl.trimEnd('/')
    val json = Json { ignoreUnknownKeys = true; explicitNulls = false }

    private fun enc(v: String) = URLEncoder.encode(v, "UTF-8").replace("+", "%20")

    /** Sends one request and returns the raw answer. */
    fun request(method: String, path: String, query: Map<String, Any?> = emptyMap(), body: String? = null): ByteArray {
        val qs = query.filterValues { it != null && it != "" }.entries.joinToString("&") { (k, v) ->
            enc(k) + "=" + enc(if (v is Iterable<*>) v.joinToString(",") else v.toString())
        }
        val conn = URL(base + path + (if (qs.isEmpty()) "" else "?$qs")).openConnection() as HttpURLConnection
        conn.requestMethod = method
        conn.connectTimeout = timeoutMs
        conn.readTimeout = timeoutMs
        conn.setRequestProperty("Accept", "application/json")
        conn.setRequestProperty("X-NWays-Api-Key", apiKey)
        conn.setRequestProperty("User-Agent", "nways-kotlin/$VERSION")
        headers.forEach { (k, v) -> conn.setRequestProperty(k, v) }
        if (body != null) {
            conn.doOutput = true
            conn.setRequestProperty("Content-Type", "application/json")
            conn.outputStream.use { it.write(body.toByteArray()) }
        }
        val status = conn.responseCode
        if (status !in 200..299) {
            val text = conn.errorStream?.use { String(it.readBytes()) } ?: ""
            val parsed = runCatching { json.parseToJsonElement(text).jsonObject }.getOrNull()
            val env = parsed?.get("error") as? JsonObject
            val reason = env?.get("reason")?.jsonPrimitive?.contentOrNull ?: (parsed?.get("code") as? JsonPrimitive)?.contentOrNull
            val message = env?.get("message")?.jsonPrimitive?.contentOrNull ?: (parsed?.get("error") as? JsonPrimitive)?.contentOrNull ?: "HTTP $status"
            throw ApiError(status, reason, message, conn.getHeaderField("Retry-After")?.toDoubleOrNull(), text)
        }
        return if (status == 204) ByteArray(0) else conn.inputStream.use { it.readBytes() }
    }

    private fun <T> decode(serializer: KSerializer<T>, bytes: ByteArray): T = json.decodeFromString(serializer, String(bytes))

    /** A hosted map style (one map load) (GET /maps/v1/styles/{style}.json) */
    fun getStyle(style: String, lang: String? = null, format: String? = null): GetStyleResponse {
        return decode(JsonElement.serializer(), request("GET", "/maps/v1/styles/${enc(style)}.json", mapOf("lang" to lang, "format" to format), null))
    }

    /** The countries the map covers (GET /maps/v1/tiles/countries.json) */
    fun getTileCountries(): GetTileCountriesResponse {
        return decode(JsonElement.serializer(), request("GET", "/maps/v1/tiles/countries.json", emptyMap(), null))
    }

    /** Removed — whole-country archives aren't part of the platform (GET /maps/v1/tiles/{tileset}.pmtiles) */
    fun getTileArchive(tileset: String): JsonElement {
        return json.parseToJsonElement(String(request("GET", "/maps/v1/tiles/${enc(tileset)}.pmtiles", emptyMap(), null)))
    }

    /** One vector tile (GET /maps/v1/tiles/{tileset}/{z}/{x}/{y}.mvt) */
    fun getTile(tileset: String, z: String, x: String, y: String): ByteArray {
        return request("GET", "/maps/v1/tiles/${enc(tileset)}/${enc(z)}/${enc(x)}/${enc(y)}.mvt", emptyMap(), null)
    }

    /** One picture tile (GET /maps/v1/tiles/raster/{theme}/{z}/{x}/{y}.png) */
    fun getRasterTile(theme: String, z: String, x: String, y: String): ByteArray {
        return request("GET", "/maps/v1/tiles/raster/${enc(theme)}/${enc(z)}/${enc(x)}/${enc(y)}.png", emptyMap(), null)
    }

    /** Font glyphs for map labels (free) (GET /maps/v1/fonts/{stack}/{range}.pbf) */
    fun getGlyphs(stack: String, range: String): ByteArray {
        return request("GET", "/maps/v1/fonts/${enc(stack)}/${enc(range)}.pbf", emptyMap(), null)
    }

    /** A map image (GET /maps/v1/staticmap) */
    fun getStaticMap(center: String? = null, zoom: Double? = null, size: String? = null, scale: Long? = null, theme: String? = null, format: String? = null, markers: List<String>? = null, path: List<String>? = null, signature: String? = null): ByteArray {
        return request("GET", "/maps/v1/staticmap", mapOf("center" to center, "zoom" to zoom, "size" to size, "scale" to scale, "theme" to theme, "format" to format, "markers" to markers, "path" to path, "signature" to signature), null)
    }

    /** Search for places, addresses and codes (GET /maps/v1/geocode) */
    fun geocode(q: String, near: String? = null, country: String? = null, limit: Long? = null, validate: Boolean? = null, lang: String? = null, fields: String? = null): GeocodeResponse {
        return decode(GeocodeResponse.serializer(), request("GET", "/maps/v1/geocode", mapOf("q" to q, "near" to near, "country" to country, "limit" to limit, "validate" to validate, "lang" to lang, "fields" to fields), null))
    }

